[CmdletBinding()]
param([switch]$RequireApproved,[string]$PolicyFile=(Join-Path $PSScriptRoot '..\docs\finance\operations-policy.json'))
$ErrorActionPreference='Stop';$root=(Resolve-Path(Join-Path $PSScriptRoot '..')).Path;$d=Get-Content -LiteralPath(Resolve-Path $PolicyFile)-Raw|ConvertFrom-Json -Depth 20
if($d.schemaVersion-ne 1-or$d.module-ne'OTOTR_FRANCHISE_FINANCE'-or$d.target-ne'PREPRODUCTION_OPERATIONS_POLICY'-or$d.status-notin@('PENDING_APPROVAL','APPROVED')-or$d.shiftSystemUsed-ne$false){throw'Invalid finance operations policy.'}
$names=@('Alarm teslimi','Olay kabulü','Correlation araması','Eskalasyon zinciri','Finansal olay çözümü','İlk 24 saat sorumluluk devri');if(@($d.drillTargets).Count-ne 6){throw'Operations policy must contain six drills.'};for($i=0;$i-lt 6;$i++){$x=$d.drillTargets[$i];if($x.id-ne('OPS-FIN-{0:d2}'-f($i+1))-or$x.name-ne$names[$i]){throw"Invalid operations policy drill: $($x.id)"}}
$approved=$d.status-eq'APPROVED'
if($approved){
 foreach($name in @('alertChannelSecretName','supportChannelSecretName')){if($d.$name-notmatch'^[A-Z][A-Z0-9_]{2,127}$'){throw"Invalid operations secret name: $name"}}
 foreach($name in @('primaryOnCallIdentitySha256','backupOnCallIdentitySha256')){if($d.$name-notmatch'^[a-f0-9]{64}$'){throw"Invalid on-call identity: $name"}};if($d.primaryOnCallIdentitySha256-eq$d.backupOnCallIdentitySha256){throw'Primary and backup on-call identities must differ.'}
 foreach($drill in $d.drillTargets){if($null-eq$drill.targetMaxMinutes-or[decimal]$drill.targetMaxMinutes-le 0){throw"Operations target missing: $($drill.id)"}}
 foreach($pair in @(@('supportSlaPolicyPath','supportSlaPolicySha256'),@('first24hResponsibilityPlanPath','first24hResponsibilityPlanSha256'),@('approval.evidencePath','approval.evidenceSha256'))){$pathValue=if($pair[0]-like'approval.*'){$d.approval.evidencePath}else{$d.($pair[0])};$hashValue=if($pair[1]-like'approval.*'){$d.approval.evidenceSha256}else{$d.($pair[1])};if($pathValue-match'^[A-Za-z]:|^\\|^/'-or$hashValue-notmatch'^[a-f0-9]{64}$'){throw"Operations policy evidence locator invalid: $($pair[0])"};$p=[IO.Path]::GetFullPath((Join-Path $root $pathValue));if(-not$p.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)-or-not(Test-Path -LiteralPath $p -PathType Leaf)-or(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()-ne$hashValue){throw"Operations policy evidence invalid: $($pair[0])"}}
 foreach($name in @('operationsLeadIdentitySha256','financeOperationsIdentitySha256','approvedAtUtc')){if([string]::IsNullOrWhiteSpace($d.approval.$name)){throw"Operations approval missing: $name"}};if($d.approval.operationsLeadIdentitySha256-notmatch'^[a-f0-9]{64}$'-or$d.approval.financeOperationsIdentitySha256-notmatch'^[a-f0-9]{64}$'-or$d.approval.operationsLeadIdentitySha256-eq$d.approval.financeOperationsIdentitySha256){throw'Operations approver identities are invalid.'};[void][DateTimeOffset]::Parse($d.approval.approvedAtUtc)
 if(($d|ConvertTo-Json -Depth 20)-match'(?i)https?://|@|\+\d{8,}|slack\.com|teams\.microsoft|webhook'){throw'Operations policy contains a private channel or contact value.'}
}else{foreach($drill in $d.drillTargets){if($null-ne$drill.targetMaxMinutes){throw"Pending operations policy contains target: $($drill.id)"}}}
Write-Host "FINANCE OPERATIONS POLICY: $($d.status)" -ForegroundColor $(if($approved){'Green'}else{'Yellow'});Write-Host 'No shift system; six drills and first-24-hour responsibility plan are approval-gated.';if($RequireApproved-and-not$approved){throw'Finance operations policy is not approved.'}
